// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LiquidityPool} from "../src/LiquidityPool.sol";

contract InvMutTest is Test {
    LiquidityPool c;
    __InvMutShare share;

    function setUp() public {
        share = new __InvMutShare();
        c = new LiquidityPool(0, bytes16(0), address(this), address(share), address(new __InvMutHandleStub()));
    }

    function testFuzz_property(bool underlyingResult, address from, address to, uint256 amount) public {
        // The share stub's return value is the switch the test controls; c must propagate it verbatim.
        share.setReturn(underlyingResult);
        vm.prank(address(this));
        bool got = c.transferFrom(from, to, amount);
        // General rule: c.transferFrom returns exactly the bool the underlying share returned.
        assertTrue(got == underlyingResult);
    }
}

contract __InvMutShare {
    bool public ret = true;
    function setReturn(bool r) external { ret = r; }
    function name() external pure returns (string memory) { return "S"; }
    function symbol() external pure returns (string memory) { return "S"; }
    function decimals() external pure returns (uint8) { return 18; }
    function totalSupply() external pure returns (uint256) { return 0; }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function allowance(address, address) external pure returns (uint256) { return 0; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external view returns (bool) { return ret; }
    function checkTransferRestriction(address, address, uint256) external pure returns (bool) { return true; }
    receive() external payable {}
    fallback() external payable {}
}

contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
    function WETH() external view returns (address) { return address(this); }
    function name() external pure returns (string memory) { return "S"; }
    function symbol() external pure returns (string memory) { return "S"; }
    function decimals() external pure returns (uint8) { return 18; }
    function totalSupply() external pure returns (uint256) { return 0; }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function allowance(address, address) external pure returns (uint256) { return 0; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    receive() external payable {}
